export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'M21 21l-5-5 M10.5 18a7.5 7.5 0 1 0 0-15 7.5 7.5 0 0 0 0 15',plus:'M12 5v14M5 12h14',minus:'M5 12h14',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',close:'m6 6 12 12M18 6 6 18',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',file:'M14 2H5v20h14V7l-5-5v5h5M8 12h8M8 16h6',folder:'M3 5h7l2 3h9v13H3V5',user:'M20 21v-3a5 5 0 0 0-5-5H9a5 5 0 0 0-5 5v3M12 9a4 4 0 1 0 0-8 4 4 0 0 0 0 8',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2',send:'m3 3 19 9-19 9 4-9-4-9M7 12h15',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4m-4 10 3 3 5-6',chart:'M3 3v18h18M7 16v-5m5 5V6m5 10V9',graph:'M8 6h8M6 8v8m12-8v8M8 18h8M6 8a2 2 0 1 0 0-4 2 2 0 0 0 0 4m12 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4M6 20a2 2 0 1 0 0-4 2 2 0 0 0 0 4m12 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4',briefcase:'M3 7h18v14H3V7m5 0V3h8v4M3 12h18M10 12v3h4v-3',upload:'M12 16V2m-5 5 5-5 5 5M3 15v7h18v-7',download:'M12 2v14m-5-5 5 5 5-5M3 17v5h18v-5',info:'M12 11v6m0-10v1M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',stop:'M6 6h12v12H6z',refresh:'M20 7V2l-4 4a8 8 0 1 0 4 10M20 7h-6',arrow:'M4 12h16m-6-6 6 6-6 6',menu:'M3 5h18M3 12h18M3 19h18',database:'M3 5a9 3 0 1 0 18 0 9 3 0 1 0-18 0v14a9 3 0 0 0 18 0V5M3 12a9 3 0 0 0 18 0',pause:'M8 5v14M16 5v14',play:'m7 3 14 9-14 9V3',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7'};
const figmaIcons=new Set(['search','user','entity-user','entity-chevron','chevron','file','check','folder','send','folder-tree']);
export const icon=(n,cls='')=>figmaIcons.has(n)?`<span class="icon figma-icon ${cls}" aria-hidden="true"><img src="/assets/figma/${n}.svg" alt=""></span>`:`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
export function btn(label,action,extra='',kind='secondary',ico=''){return `<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`}
export const link=(label,id,cls='')=>`<a href="#/${id}" class="${cls}">${label}</a>`;
export const tag=(text,type='neutral')=>`<span class="tag ${type}">${esc(text)}</span>`;
export const badge=(status)=>tag(status, /完成|已发布|通过|Ready|DONE|就绪|已复核|有效/.test(status)?'success':/失败|拒绝|异常|FAILED|Error|撤回|冲突/.test(status)?'danger':/运行|执行|RUNNING|Planning/.test(status)?'blue':/待|暂停|PAUSED|部分|Permission|Processing/.test(status)?'warning':'neutral');
export const field=(label,name,value='',type='text',opts='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${opts}></label>`;
export function select(label,name,values,value,opts=''){return `<label class="field"><span>${label}</span><select name="${name}" ${opts}>${values.map(v=>`<option ${String(value)===String(v)?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
export const area=(label,name,value='',opts='')=>`<label class="field"><span>${label}</span><textarea name="${name}" ${opts}>${esc(value)}</textarea></label>`;
export const check=(label,name,value=false,opts='')=>`<label class="checkbox"><input type="checkbox" name="${name}" ${value?'checked':''} ${opts}>${label}</label>`;
export const empty=(title,detail,action='')=>`<div class="empty">${icon('folder')}<h3>${title}</h3><p>${detail}</p>${action}</div>`;
export const note=(text,kind='info')=>`<div class="notice ${kind}">${icon(kind==='danger'?'shield':'info')}<div>${text}</div></div>`;
export const heading=(title,desc='',actions='',eyebrow='')=>`<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div><div class="actions">${actions}</div></div>`;
export function table(headers,rows,caption=''){return `<div class="table-wrap"><table>${caption?`<caption>${caption}</caption>`:''}<thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${empty('没有符合条件的记录','调整筛选条件，或清除筛选后重试。')}</td></tr>`}</tbody></table></div>`}
export const section=(title,body,action='',cls='')=>`<section class="section ${cls}"><div class="section-title"><h2>${title}</h2>${action}</div>${body}</section>`;
export const kv=(obj)=>`<dl class="kv">${Object.entries(obj).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${v}</dd>`).join('')}</dl>`;
export const progress=(v)=>`<div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${v}" aria-label="任务完成进度"><span style="width:${v}%"></span></div>`;
export const steps=(items,index)=>`<ol class="wizard-steps">${items.map((x,i)=>`<li class="${i===index?'active':i<index?'done':''}"><span>${i<index?icon('check'):i+1}</span>${x}</li>`).join('')}</ol>`;
